let _catPids={}, _catLinks={};
/* v579: «التصنيفات دخوه وهوسة» — قاعدة وحدة بكل مكان (لوحة المحل + الزبون + السيرفر shop_products_move):
   المادة داخل التصنيف إذا اسمه مكتوب عليها (cat) أو مربوطة بيه (product_categories).
   قبل: لوحة المحل تقرا الربط بس، والزبون الاسم إذا ماكو ربط — بغداد ماركت: 975 مادة بأسماء أقسام و3 بس مربوطة ← كل قسم «0 منتج»،
   و«إضافة منتجات» تبيّن الـ982 كلها، و«إزالة» تمسح الاسم فالمادة تختفي من الزبون. */
const NOCAT_ID='__none__';
function _pcat(p){ return String((p&&p.cat)||'').trim() }
function _catHasName(n){ return !!n && (myCats||[]).some(c=>String(c.name||'').trim()===n) }
function _isNoCat(p){ const pid=_cpPid(p); return !_catHasName(_pcat(p)) && !Object.keys(_catLinks).some(k=>_catLinks[k].has(pid)) }
function _catRecount(){
  _catCnt={}; _catPids={};
  const ps=_cpProducts(), byName={};
  ps.forEach(p=>{ const n=_pcat(p); if(n) (byName[n]=byName[n]||[]).push(_cpPid(p)) });
  const have=new Set(ps.map(_cpPid));
  (myCats||[]).forEach(c=>{
    const set=new Set(byName[String(c.name||'').trim()]||[]);
    (_catLinks[c.id]||new Set()).forEach(id=>{ if(have.has(id)) set.add(id) });
    _catPids[c.id]=set; _catCnt[c.id]=set.size;
  });
}
/* أعضاء التصنيف — الرئيسي = منتجاته + منتجات أقسامه الفرعية */
function _catMemberIds(c){
  if(!c) return [];
  if(c.id===NOCAT_ID) return _cpProducts().filter(_isNoCat).map(_cpPid);
  const set=new Set(_catPids[c.id]||[]);
  if(!c.parent_id) _cSubs(myCats,c.id).forEach(x=>(_catPids[x.id]||[]).forEach(p=>set.add(p)));
  return [...set];
}

const noRow = noCat ? `<div class="cat-row nocat" onclick="catProdsOpen('${NOCAT_ID}')">
    <div class="cat-nm"><b>بلا تصنيف</b><span>${noCat} منتج — الزبون ما يلگاهم بأي قسم. اضغط وانقلهم</span></div>
    <span class="cat-ic ed" aria-hidden="true"><svg class="wic" viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M15 6l-6 6 6 6"/></svg></span></div>` : '';
let html=topRow+noRow+'<div id="catRows">'+_tops.map(c=>{

function tImg320(u){ u=oImg(u); return (/^\/m\/[\w\/.-]+\.webp$/.test(u) && !/\.[ts]\.webp$/.test(u)) ? u.replace(/\.webp$/,'.t.webp') : u }
/* v571: «ناس نتهم تعبان» — بالنت البطيء الكروت تاخذ نسخة 160px (أخف ٤ مرات، ‎~3KB) بدل 320px. تنصنع وقت النشر (tools/sbimg.mjs).
   إذا ما موجودة (صورة جديدة قبل النشر الجاي) ← ترجع للـ320 وحدها (معالج الخطأ تحت) */
var __imgLite=false;
function tImg(u){ const t=tImg320(u); return (__imgLite && /^\/m\/[\w\/.-]+\.t\.webp$/.test(t)) ? t.replace(/\.t\.webp$/,'.s.webp') : t }

const q=_cpQ1, vir=!!(_cpCat&&_cpCat.virtual);
const all=ps.filter(p=>_cpLinks.includes(_cpPid(p))).filter(p=>!q || String(p.name||'').includes(q));
const list=all.slice(0,CP_MAX);
const own=_cpCat?String(_cpCat.name||'').trim():'';

const par=_cpParent?String(_cpParent.name||'').trim():'';
const sibs=_cpParent?_cSubs(myCats,_cpParent.id).map(x=>String(x.name||'').trim()):[];
const rank=p=>{ const c=_pcat(p); return (par && c===par)?0 : (sibs.includes(c)?1 : (_isNoCat(p)?2:3)) };
const all=ps.filter(p=>_cpPid(p) && !_cpLinks.includes(_cpPid(p)))
            .filter(p=>!q || String(p.name||'').includes(q))
            .map((p,i)=>({p,i,r:rank(p)})).sort((a,b)=>a.r-b.r||a.i-b.i).map(x=>x.p);
const list=all.slice(0,CP_MAX);
const allSel=list.length && list.every(p=>_cpSel.includes(_cpPid(p)));
const nm=esc(_cpCat?_cpCat.name:'');

/* v585: «حذف» بصفحة التصنيف — يسأل أول، وبعد الحذف يختفي من القائمة فوراً */
async function cpDelOne(pid){
  if(!(await delProduct(pid))) return;
  try{ if(myShopDoc && Array.isArray(myShopDoc.products)) myShopDoc.products=myShopDoc.products.filter(x=>_cpPid(x)!==pid) }catch(e){}
  _cpLinks=_cpLinks.filter(x=>x!==pid);
  cpPaintList();
}

/* v579: نقل/إضافة بخطوة وحدة على السيرفر (shop_products_move) — الاسم المكتوب والربط يتعدّلون سوة */
let _cmvBusy=false;
async function _catMoveRun(ids, fromId, toCat, keep){
  if(_cmvBusy || !ids.length) return false;
  _cmvBusy=true;

    await rpc('shop_products_move',{p_shop:me.shopId, p_ids:ids.map(String), p_from:fromId||null, p_to:toCat?toCat.id:null, p_keep:!!keep});
  }catch(e){ _cmvBusy=false; toast('ما گدرنا ننقل: '+String(e.message||e).slice(0,90)); return false }
  /* نحدّث نسختنا المحلية بنفس قاعدة السيرفر */
  const set=new Set(ids.map(String)), from=fromId?(myCats.find(c=>c.id===fromId)||null):null, fromNm=from?String(from.name||'').trim():null;
  if(!keep) _cpProducts().forEach(p=>{ if(set.has(_cpPid(p)) && (!from || _pcat(p)===fromNm)) p.cat=toCat?String(toCat.name||'').trim():'' });
  if(!keep && fromId && _catLinks[fromId]) ids.forEach(id=>_catLinks[fromId].delete(String(id)));
  if(toCat) _cpProducts().forEach(p=>{ if(set.has(_cpPid(p)) && _pcat(p)!==String(toCat.name||'').trim()) (_catLinks[toCat.id]=_catLinks[toCat.id]||new Set()).add(_cpPid(p)) });
  _catRecount();
  _cmvBusy=false;
  try{ renderStMenu() }catch(e){}
  return true;
}
async function cpAddSelected(keep){
  if(!_cpCat || _cpCat.virtual || !_cpSel.length) return;
  const n=_cpSel.length;
  if(!(await _catMoveRun(_cpSel.slice(), null, _cpCat, keep))) return;
  toast(keep ? n+' منتج صار يطلع بـ «'+_cpCat.name+'» هم' : n+' منتج انتقل لـ «'+_cpCat.name+'» ✓');

/* v579: نقل منتج واحد.  v581: «هوسة» — 92 قسم كبطاقات طويلة ← بحث + «قريب منه» + الأقسام الرئيسية شبكة صغيرة، وتضغط الرئيسي تطلع فروعه */
let _cmv={pid:'', view:'', q:''};
function cpMoveOne(pid){
  const p=_cpProducts().find(x=>_cpPid(x)===String(pid)); if(!p || !_cpCat) return;
  _cmv={pid:String(pid), view:'', q:''};
  let el=document.getElementById('cmvSheet');
  if(!el){ el=document.createElement('div'); el.id='cmvSheet'; el.onclick=e=>{ if(e.target===el) el.classList.remove('on') }; document.body.appendChild(el) }
  el.innerHTML=`<div class="cmv-sheet"><div class="prq-sh-h"><b>وين تنقل «${esc(p.name||'')}»؟</b><button type="button" class="as-x" onclick="document.getElementById('cmvSheet').classList.remove('on')" aria-label="سد">✕</button></div>
    <div class="cmv-now" id="cmvNow"></div>
    <div class="cp-srch cmv-q"><svg class="wic" viewBox="0 0 24 24" fill="none" stroke="currentColor"><circle cx="11" cy="11" r="6.5"/><path d="M16 16l4.5 4.5"/></svg><input type="text" placeholder="دوّر على القسم…" oninput="_cmv.q=this.value.trim();_cmv.view='';cmvPaint()"></div>
    <div id="cmvBody"></div></div>`;
  el.classList.add('on');
  cmvPaint();
}
function cmvPaint(){
  const box=document.getElementById('cmvBody'); if(!box) return;
  const pid=_cmv.pid, P=v=>JSON.stringify(v).replace(/"/g,'&quot;');
  const here=new Set(myCats.filter(c=>(_catPids[c.id]||new Set()).has(pid)).map(c=>c.id));
  const nowEl=document.getElementById('cmvNow');
  if(nowEl){ const hs=myCats.filter(c=>here.has(c.id)).map(c=>{ const pr=c.parent_id&&myCats.find(x=>x.id===c.parent_id); return (pr?pr.name+' › ':'')+c.name });
