  const cur=(_pv&&_pv.res&&_pv.res.ok&&String(orderCode||'').toUpperCase()!==st.code)?Number(_pv.res.discount||0):0;
  if(sub<min){ WH.apply={k:'min',need:min-sub}; return }
  if((orderCode||'').trim() && String(orderCode).toUpperCase()!==st.code && cur>pz){ WH.apply={k:'bigger'}; return }
  orderCode=st.code; WH.skip=false; WH.apply={k:'ok'};
}

